'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], P=Planner, KEY='still-days-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={version:1,start:'2026-10-23',tz:'America/New_York',days:{},map:{},inbox:[]}, storageOK=true;
try{let raw=localStorage.getItem(KEY);if(raw){let v=JSON.parse(raw);if(v.version===1&&v.days&&v.map&&Array.isArray(v.inbox))state={...state,...v};}}catch(e){storageOK=false;}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:state.tz,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
let selected=today(),view='today',journalTab='morning',timerLeft=25*60,timerRunning=false,timerInterval=null,dragId=null;
let calendarMode='day',calendarScroll={},scheduleUndo=new Map();
let visitTip=FlowTips.pick(state.lastTipId);state.lastTipId=visitTip.id;
function day(){if(!state.days[selected])state.days[selected]={morning:{},night:{},weekly:{},metrics:{},tasks:[]};return state.days[selected]}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#saveState').textContent='Saved on this device · export a backup in settings'}catch(e){storageOK=false;$('#saveState').textContent='Could not save · export your entries now';toast('Browser storage unavailable or full. Export a backup in settings.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4200)}
const addDays=(date,n)=>{let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayNum=d=>Math.floor((new Date(d+'T12:00:00')-new Date(state.start+'T12:00:00'))/86400000)+1;
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});
const hasEntry=d=>{let x=state.days[d];return x&&((x.tasks||[]).length||Object.keys(x.metrics||{}).length||Object.values(x.morning||{}).some(Boolean)||Object.values(x.night||{}).some(Boolean)||Object.values(x.weekly||{}).some(Boolean)||Object.values(x.focus||{}).some(Boolean))};
const field=(label,key,value,placeholder='',type='textarea')=>`<label class="field"><span>${label}</span>${type==='textarea'?`<textarea data-bind="${key}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`:`<input type="${type}" data-bind="${key}" value="${esc(value)}" placeholder="${esc(placeholder)}">`}</label>`;
const select=(label,key,value,options)=>`<label class="field"><span>${label}</span><select data-bind="${key}">${options.map(([v,t])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${t}</option>`).join('')}</select></label>`;
function datebar(){let n=dayNum(selected);return `<div class="datebar"><button id="prevDate" aria-label="Previous day">←</button><input type="date" id="dateSelect" aria-label="Selected date" value="${selected}" style="width:150px"><button id="nextDate" aria-label="Next day">→</button><button id="goToday" class="small">Today</button><div class="day-status"><span class="mono">${n>=1&&n<=30?'Day '+String(n).padStart(2,'0')+' / 30':'Outside reset'}</span><span class="pill">${[4,5].includes(new Date(selected+'T12:00:00').getDay())?'Thursday / Friday focus day':'Your daily plan'}</span></div></div>`}
function morning(compact=false){let m=day().morning;return `${field('What are you most excited about today?','morning.excited',m.excited,'A person, an idea, a small adventure—what’s calling to you?')}${field('What are you most scared of today?','morning.fear',m.fear,'What feels daunting? What might help you take the first step?')}${field('What do I want to do today?','morning.must',m.must,'Tell me everything on your mind. I’ll turn it into tasks with time estimates.')}${voiceControl('[data-bind="morning.must"]')}${compact?'':field('What would make today feel like a day well lived?','morning.meaning',m.meaning,'A good conversation, a drawing, an hour outside…')}<div class="inline-fields">${select('Energy right now','morning.energy',m.energy||3,[[1,'1 · depleted'],[2,'2 · low'],[3,'3 · okay'],[4,'4 · good'],[5,'5 · bright']])}${field('Getting up at','morning.wake',m.wake||'11:00','','time')}</div>${compact?'':`<div class="inline-fields">${field('Work ends by','morning.finish',m.finish||'23:00','','time')}${field('Where would I love to think today?','morning.place',m.place,'Library / café / desk','text')}</div>`}${mindfulMorning()}<button class="primary wide-btn" id="generatePlan">Shape my day ↗</button><p class="small" style="margin:10px 0 0">${typeof AIPlanner!=='undefined'&&AIPlanner.config().endpoint?'AI makes a to-do list with time estimates, then fits work into your existing focus blocks. Your daily routine stays.':'Your default rhythm is ready. Connect AI in Settings to turn a brain dump into specific tasks.'}</p>`}
function currentSchedule(){let d=day();return d.schedule||P.makePlan(selected,d.morning,P.defaults(selected)).blocks}
const noteCopy=text=>({"Phone stays away from bed. A gentle start counts.": "Leave your phone away from bed while you get ready.", "Desk or library: write the question, current guess, and what would count as progress.": "Write your question, what you think so far, and what you want to finish.", "Start with a small answerable piece; your fear is a reflection prompt, not a diagnosis.": "Start with the part you can answer in this session.", "One question. One visible artifact.": "Work through one question and save your notes or result.", "Stay with the project; write a decision, result, or blocker.": "Continue where you left off. Write down what you found or where you got stuck.", "Choose project 2 or 3 deliberately. Check only what is needed.": "Pick the next task for project 2 or 3 before opening its tabs.", "Leave a little space unfilled.": "Take a break without opening a feed.", "Food and connection are part of the plan.": "Eat dinner and catch up with friends.", "Keep something you enjoy without needing it to prove your worth.": "Work on something you enjoy.", "Your worry is kept visible; its meaning is not inferred from keywords.": "Your answer about fear is saved in the journal and does not change the plan."})[text]||text;
function agendaSchedule(){let blocks=currentSchedule();return `<div class="section-head"><h2>Make time for what matters</h2><button id="addBlock">+ Block</button></div><div class="timeline">${blocks.map((b,i)=>`<div class="block ${esc(b.type)}" draggable="${b.type!=='fixed'}" data-id="${esc(b.id)}"><div><div class="block-time">${esc(b.start)} — ${esc(P.time(P.mins(b.start)+b.duration))} · ${b.duration} MIN</div><div class="block-title">${esc(b.title)}</div>${b.note?`<div class="block-note">${esc(noteCopy(b.note))}</div>`:''}</div><div class="block-tools"><button data-edit="${i}" aria-label="Edit ${esc(b.title)}">✎</button>${b.type!=='fixed'?`<button data-move="${i},-1" aria-label="Move block earlier">↑</button><button data-move="${i},1" aria-label="Move block later">↓</button>`:''}</div></div>`).join('')}</div><p class="small schedule-note">Class and meeting times are estimates. Edit them to match your calendar. Changes apply to this date.</p>${day().planReasons?`<details class="small"><summary>Why this schedule?</summary>${day().planReasons.map(r=>`<p>${esc(noteCopy(r))}</p>`).join('')}</details>`:''}`}
function tasks(){let d=day();return `<div class="section-head"><h2>What I’ll make happen</h2><span class="mono">${d.tasks.filter(t=>t.done).length} / ${d.tasks.length}</span></div><form id="taskForm" class="task-input"><input id="taskText" aria-label="New daily task" placeholder="Add a task…" maxlength="300" required><button aria-label="Add task">＋</button></form><div class="tasks">${d.tasks.length?d.tasks.map((t,i)=>`<div class="task ${t.done?'done':''}"><input type="checkbox" data-task="${i}" aria-label="Complete ${esc(t.text)}" ${t.done?'checked':''}><span class="task-title">${esc(t.text)}${Number.isFinite(t.duration)&&t.duration>0?'<span class="task-estimate">'+(t.estimated?'≈ ':'')+esc(t.duration)+' min'+(t.priority?' · Priority '+esc(t.priority):'')+'</span>':''}</span><button class="icon-btn" data-delete-task="${i}" aria-label="Remove task">×</button></div>`).join(''):'<div class="empty">What are you ready to get started on?</div>'}</div>`}
function metrics(){let m=day().metrics;const num=(label,key,min,max,step=1)=>`<div class="tracker-row"><label for="metric-${key}">${label}</label><input id="metric-${key}" type="number" min="${min}" max="${max}" step="${step}" data-bind="metrics.${key}" value="${esc(m[key])}" aria-label="${label}"></div>`;return `<div class="section-head"><h2>Watch your progress</h2><span>↗</span></div><p class="small">Fill in what you know. Leave the rest blank.</p>${num('Sleep · hours','sleep',0,24,.5)}${num('Minutes to leave bed','bed',0,1440)}${num('Coffee · cups','coffee',0,20,.5)}${num('Walk / movement · min','movement',0,1440)}${num('Scrolling · min','scroll',0,1440)}${num('Research outputs','artifacts',0,100)}${num('Brain fog · 0–10','fog',0,10)}${num('Flow / absorption · 0–10','flow',0,10)}<div class="tracker-row"><label for="noFeed">Kept my feed boundaries</label><input id="noFeed" data-bind="metrics.boundary" type="checkbox" ${m.boundary?'checked':''}></div><div class="tracker-row"><label for="ownThought">Wrote my own thoughts first</label><input id="ownThought" data-bind="metrics.ownThought" type="checkbox" ${m.ownThought?'checked':''}></div>`}


function voiceControl(selector){return `<div class="voice-control"><button type="button" data-voice-for='${esc(selector)}' aria-pressed="false"><svg aria-hidden="true" width="12" height="15" viewBox="0 0 16 20" fill="none"><rect x="5" y="1" width="6" height="11" rx="3" stroke="currentColor" stroke-width="1.5"/><path d="M2 8v2a6 6 0 0 0 12 0V8M8 16v3M5 19h6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg> Use voice</button><span class="small" data-voice-status role="status">Browser dictation may process audio online. Review the text before using it.</span></div>`}
function nowMinutes(){let t=new Intl.DateTimeFormat('en-GB',{timeZone:state.tz,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());return P.mins(t)}
function weekStrip(){let weekday=new Date(selected+'T12:00:00').getDay(),monday=addDays(selected,-((weekday+6)%7));return Array.from({length:7},(_,i)=>{let dt=addDays(monday,i);return `<button class="cal-date ${dt===selected?'selected':''}" data-date="${dt}" aria-label="Open ${dateLabel(dt)}"><span>${new Date(dt+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</span><b>${Number(dt.slice(-2))}</b></button>`}).join('')}
function schedule(){let blocks=currentSchedule(),d=day();let agenda=agendaSchedule();agenda=agenda.slice(agenda.indexOf('<div class="timeline">'));return `<div class="section-head cal-heading"><div><span class="eyebrow">YOUR DAY, WITH ROOM TO MOVE</span><h2>Make time for what matters</h2></div><button id="addBlock" aria-label="Add calendar block">＋</button></div><div class="cal-toolbar"><div class="cal-view-toggle" role="group" aria-label="Schedule view"><button class="${calendarMode==='day'?'active':''}" data-cal-mode="day">Day</button><button class="${calendarMode==='agenda'?'active':''}" data-cal-mode="agenda">Agenda</button></div><button class="small" id="undoSchedule" ${(scheduleUndo.get(selected)||[]).length?'':'disabled'} aria-label="Undo last schedule change">↶ Undo</button>${d.schedule?'<button class="small feedback-button" id="feedbackBtn">Give feedback ↗</button>':''}</div>${calendarMode==='agenda'?agenda:CalendarUI.markup({items:blocks,week:weekStrip(),date:esc(new Date(selected+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric'})),weekday:esc(new Date(selected+'T12:00:00').toLocaleDateString('en-US',{weekday:'long'}))},esc,selected===today()?nowMinutes():null)}<details class="calendar-help"><summary>Calendar controls</summary><p>Move blocks by dragging. Resize from the top or bottom edge. Fixed commitments stay locked; use their edit button to change them. Double-click free space to add a block.</p><p>With a block focused: Alt + ↑ / ↓ moves it by 15 minutes; add Shift to resize. Enter opens its editor. Escape cancels a drag.</p><p>Changes cannot overlap another block. Feedback can rearrange flexible blocks for you. Undo reverses edits made in this session.</p></details>${calendarMode==='day'?'<p class="small schedule-note">Class and meeting times are estimates. Edit them to match your calendar.</p>':''}`}
function rememberSchedule(){let list=scheduleUndo.get(selected)||[];list.push(structuredClone(currentSchedule()));scheduleUndo.set(selected,list.slice(-20))}
function commitSchedule(blocks,message='Schedule updated',focusId=null){rememberSchedule();day().schedule=blocks;save();let scroll=window.scrollY;render();window.scrollTo({top:scroll,behavior:'instant'});if(focusId)$$('[data-event-id]').find(el=>el.dataset.eventId===focusId)?.focus({preventScroll:true});SiteMotion.pulse($('#dayCalendar'));toast(message)}
function bindCalendar(){VoiceInput.bind();$$('[data-cal-mode]').forEach(b=>b.onclick=()=>{calendarMode=b.dataset.calMode;render()});$('#undoSchedule')?.addEventListener('click',()=>{let list=scheduleUndo.get(selected)||[];if(!list.length)return;day().schedule=list.pop();save();render();toast('Previous schedule restored.')});$('#feedbackBtn')?.addEventListener('click',openFeedback);CalendarUI.bind({getBlocks:currentSchedule,scroll:calendarScroll[selected],onScroll:v=>calendarScroll[selected]=v,edit:id=>editBlock(currentSchedule().findIndex(b=>b.id===id)),create:(start,duration)=>editBlock(-1,{start,duration}),commit:commitSchedule,notify:toast,nowMinutes});}
function openFeedback(){VoiceInput.stop();let initial=structuredClone(currentSchedule()),d=day(),result=null;let el=modal(`<div class="section-head"><div><span class="eyebrow">MAKE IT FIT YOUR DAY</span><h2>What would feel better?</h2></div><button type="button" id="closeFeedback" aria-label="Close feedback">✕</button></div><p>Tell me what you want to move or make shorter or longer. You’ll see the changes before they are saved.</p><label class="field"><span>How would you like to adjust your day?</span><textarea id="feedbackText" placeholder="Move dinner to 7 pm; make walk 30 minutes">${esc(d.feedbackDraft||'')}</textarea></label>${voiceControl('#feedbackText')}<details class="feedback-examples"><summary>What can I ask?</summary><p>“Move dinner to 7 pm” · “Make walk 30 minutes” · “Move fun side project to 8 pm”. Use a semicolon between requests. Pick a specific block below if several names match.</p><p>This version handles these requests with local rules. It does not send your journal to an AI service.</p></details><details class="optional-prompts"><summary>Or adjust a specific block</summary><label class="field"><span>Block</span><select id="feedbackBlock"><option value="">Choose a flexible block…</option>${initial.filter(b=>b.type!=='fixed').map(b=>`<option value="${esc(b.id)}">${esc(b.title)}</option>`).join('')}</select></label><div class="inline-fields"><label class="field"><span>New start (optional)</span><input type="time" id="feedbackStart"></label><label class="field"><span>New duration in minutes (optional)</span><input type="number" min="15" max="720" step="5" id="feedbackDuration"></label></div></details><label class="feedback-ripple"><input type="checkbox" id="rippleFeedback" checked> Move other flexible blocks out of the way</label><p id="feedbackError" class="small" role="alert"></p><div id="feedbackPreview"></div><div class="button-row"><button class="primary" id="previewFeedback">Preview changes</button><button id="applyFeedback" hidden>Apply changes</button><button id="cancelFeedback">Keep current day</button></div>`);VoiceInput.bind(el);let invalidate=()=>{result=null;el.querySelector('#applyFeedback').hidden=true;el.querySelector('#feedbackPreview').innerHTML='';el.querySelector('#feedbackError').textContent=''};el.querySelector('#feedbackText').oninput=e=>{d.feedbackDraft=e.target.value;save();invalidate()};for(let id of ['feedbackBlock','feedbackStart','feedbackDuration','rippleFeedback'])el.querySelector('#'+id).onchange=invalidate;let close=()=>{VoiceInput.stop();el.close()};el.addEventListener('close',VoiceInput.stop);el.querySelector('#closeFeedback').onclick=close;el.querySelector('#cancelFeedback').onclick=close;el.querySelector('#previewFeedback').onclick=()=>{VoiceInput.stop();let id=el.querySelector('#feedbackBlock').value,ripple=el.querySelector('#rippleFeedback').checked;if(id){let patch={},time=el.querySelector('#feedbackStart').value,duration=el.querySelector('#feedbackDuration').value;if(time)patch.start=time;if(duration)patch.duration=Number(duration);result=CalendarModel.adjust(initial,id,patch,ripple)}else result=CalendarModel.feedback(initial,el.querySelector('#feedbackText').value,ripple);if(!result.ok){el.querySelector('#feedbackError').textContent=result.error;el.querySelector('#applyFeedback').hidden=true;return}if(!result.changes.length){el.querySelector('#feedbackError').textContent='No changes yet. Choose a new time or duration.';return}el.querySelector('#feedbackError').textContent='';el.querySelector('#feedbackPreview').innerHTML=`<h3>Your updated day</h3>${result.changes.map(b=>{let old=initial.find(x=>x.id===b.id);return `<div class="feedback-change"><strong>${esc(b.title)}</strong><span>${old.start} · ${old.duration} min → ${b.start} · ${b.duration} min</span></div>`}).join('')}<p class="small">Fixed commitments keep their times. Nothing changes until you apply this.</p>`;el.querySelector('#applyFeedback').hidden=false;SiteMotion.pulse(el.querySelector('#feedbackPreview'))};el.querySelector('#applyFeedback').onclick=()=>{if(!result?.ok)return;d.feedbackHistory??=[];d.feedbackHistory.push({request:el.querySelector('#feedbackText').value,date:new Date().toISOString(),changes:result.changes.map(b=>({title:b.title,start:b.start,duration:b.duration}))});d.feedbackHistory=d.feedbackHistory.slice(-20);close();commitSchedule(result.blocks,'Your adjustments are saved.');};}

function tipBody(t,showSources=true){let src=FlowTips.sources[t.source];return `<div class="tip-meta">${showSources?'<span class="tag">'+esc(t.kind)+'</span>':''}<span class="mono">${esc(t.time)}</span></div><h3 class="tip-title">${esc(t.title)}</h3><ol class="tip-steps">${t.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${showSources?'<details class="tip-evidence"><summary>What the source supports</summary><p>'+esc(t.why)+'</p></details><a class="source-link" href="'+src.url+'" target="_blank" rel="noopener noreferrer">'+esc(src.name)+' ↗</a>':''}`}
function tipCard(){return `<section class="card sage" id="visitTip"><div class="section-head"><h2>A little way in</h2><span class="mono">TRY ONE THING</span></div><div aria-live="polite">${tipBody(visitTip,false)}</div><div class="button-row"><button id="nextTip">Another idea ↻</button><button id="recordTip" class="small">Try this today</button><button class="small" data-open-tips>All ${FlowTips.tips.length} tips ↗</button></div></section>`}
function focusNotebook(){let f=day().focus||{};return `<section class="card blue" id="focusNotes"><div class="section-head"><h2>Meet your next good idea</h2><span class="mono">OPTIONAL / BEFORE WORK</span></div><p class="small">Give your session a clear question and a finish you can recognize.</p>${field('What question am I excited to explore?','focus.question',f.question,'For example: which environment would expose unsafe swarm behavior?')}${field('What would count as progress in this session?','focus.finish',f.finish,'A comparison paragraph, one test, or a decision with reasons.')}${field('Before I switch: where did I stop, and how will I return?','focus.resume',f.resume,'I stopped at… Next I will… I will return at…')}<div class="small">Adapted from flow research and ready-to-resume planning.</div><a class="source-link" href="https://www.nature.com/articles/s44271-024-00115-3" target="_blank" rel="noopener">Flow research framework ↗</a><a class="source-link" href="https://pubsonline.informs.org/doi/10.1287/orsc.2017.1184" target="_blank" rel="noopener">Leroy & Glomb: interruption study ↗</a><details class="optional-prompts"><summary>What am I trying, and how did it feel?</summary>${field('Technique I tried','focus.technique',f.technique,'Choose “Try this today” on a tip, or write your own.','text')}${field('What helped me settle into work? What got in the way?','focus.observation',f.observation,'Note the task, place, and how absorbed you felt. A single session cannot prove a cause.')}</details></section>`}
function mindfulMorning(){let m=day().morning;return `<details class="optional-prompts"><summary>Want to turn an intention into a plan?</summary><p class="small">Optional WOOP exercise: picture your wish and its best outcome, then name an inner obstacle and a response.</p>${field('Wish: what is something important and achievable today?','morning.wish',m.wish,'Choose something you want to work toward.')}${field('Outcome: how would it feel if it happened?','morning.outcome',m.outcome,'Pause to imagine the best result.')}${field('Obstacle: what in me might get in the way?','morning.obstacle',m.obstacle,'For example: reaching for X while I wait.')}${field('Plan: if that happens, what will I do?','morning.ifthen',m.ifthen,'If I reach for X, then I will write my own answer first.')}<a class="source-link" href="https://woopmylife.org/en/practice" target="_blank" rel="noopener">Adapted from Oettingen’s WOOP practice guide ↗</a></details>`}
function weeklyExperiment(){let w=day().weekly;return `<details class="optional-prompts"><summary>A five-minute Plus Minus Next review</summary>${field('Plus: what worked or gave me energy?','weekly.plus',w.plus,'Work, friendships, rest—anything that mattered.')}${field('Minus: what did not work?','weekly.minus',w.minus,'What would you rather not repeat?')}${field('Next: what would I like to try?','weekly.next',w.next,'A change to test in the coming week.')}<a class="source-link" href="https://nesslabs.com/plus-minus-next" target="_blank" rel="noopener">Anne-Laure Le Cunff · Ness Labs ↗</a></details>`}
function tipLibrary(){return `<section class="tips-library" id="tipLibrary"><div class="phase-heading"><div><span class="eyebrow">SMALL EXPERIMENTS / CHECKED SOURCES</span><h2>Find your own way in.</h2></div><p>Try one. Keep what helps you do the work you care about.</p></div><p class="small">Flow is not something a trick can guarantee. Labels distinguish studies, author recommendations, and our practical applications. Suggested timings marked “to try” are convenient starting points, not measured thresholds. Research examples and journal wording are adapted for your day.</p><div class="two-col">${FlowTips.tips.map(t=>`<section class="card">${tipBody(t)}</section>`).join('')}</div><p class="small">About mental multiplication: I could not verify a reliable pre-work flow benefit, so it is not included as a recommended technique.</p></section>`}

function renderToday(){return `<section class="hero"><div><div class="eyebrow">A PERSONAL RESET · ${esc(dateLabel(selected))}</div><h1>A little room<br>to <em>think.</em></h1><p>Make space for your best ideas,<br>and a day you look forward to.</p></div><div class="hero-art"><span class="art-star">✳</span><img src="sink.png" alt="An ivory scalloped porcelain sink with silver taps"><span class="art-caption">wash away the noise ↗</span></div></section>${datebar()}<nav class="day-steps" aria-label="Move through your day"><a href="#wake"><span>01</span> Morning <span>↘</span></a><a href="#focus"><span>02</span> Daytime <span>↘</span></a><a href="#close"><span>03</span> Evening <span>↘</span></a></nav>
<section class="day-phase" id="wake" aria-labelledby="wake-title"><div class="phase-heading"><div><span class="eyebrow">01 / MORNING</span><h2 id="wake-title">What could today bring?</h2></div><p>Start with what excites you. Give something important your attention.</p></div><div class="today-grid"><section class="card pink"><div class="section-head"><h2>Hello, today</h2><span class="mono">MORNING / 02 MIN</span></div>${morning(true)}<div class="link-row"><a class="tarot" href="https://randomtarotcard.com/" target="_blank" rel="noopener noreferrer"><span class="tarot-star">✧</span> Pull a morning card ↗</a><button class="small" data-journal="morning">Full journal</button></div></section><div class="stack">${tipCard()}<section class="card">${tasks()}</section><section class="card"><div class="section-head"><h2>Thirty days of possibility</h2><span class="mono">YOUR SEASON</span></div><div class="month-strip">${Array.from({length:30},(_,i)=>{let dt=addDays(state.start,i);return `<button class="day-dot ${dt===today()?'current':''} ${dt===selected?'selected':''} ${hasEntry(dt)?'recorded':''}" data-date="${dt}" aria-label="Open day ${i+1}, ${dt}">${i+1}</button>`}).join('')}</div></section></div></div></section>
<section class="day-phase" id="focus" aria-labelledby="focus-title"><div class="phase-heading"><div><span class="eyebrow">02 / THROUGH THE DAY</span><h2 id="focus-title">Follow your curiosity.</h2></div><p>There’s an idea here worth exploring. Give yourself time to find it.</p></div><div class="today-grid"><section class="card">${schedule()}</section><div class="stack">${focusNotebook()}<section class="card"><div class="section-head"><h2>Find your flow</h2><span>✳</span></div><p class="caption">Your personal warm-up</p><ol class="ritual"><li>Pick a place to work. Put your phone away.</li><li>Write for five minutes to get started.</li><li>Choose one question and what you want to finish.</li><li>If you feel stuck, make the question smaller.</li><li>Save unrelated ideas for later.</li></ol><p class="small">You said a new place, coffee, and writing help you get started. Try the routine and see how it goes.</p><div class="timer" id="timerDisplay">${timerText()}</div><div class="timer-controls"><button id="timerStart">${timerRunning?'Pause':'Begin 25 min'}</button><button id="timerReset" aria-label="Reset timer">↺</button></div></section><section class="card"><div class="section-head"><h2>Ideas for another day</h2><span class="mono">WORTH COMING BACK TO</span></div><p class="small">Save ideas here so you can finish what you are working on.</p><form id="quickIdea" class="task-input"><input id="ideaText" aria-label="Capture an idea" placeholder="An idea you want to come back to…" required><button aria-label="Save idea">＋</button></form><button class="small" data-open-inbox style="margin-top:12px">Open collection (${state.inbox.length}) ↗</button></section></div></div></section>
<section class="day-phase" id="close" aria-labelledby="close-title"><div class="phase-heading"><div><span class="eyebrow">03 / EVENING</span><h2 id="close-title">What will you remember?</h2></div><p>Celebrate what happened. Let tomorrow begin with something to look forward to.</p></div><div class="today-grid"><section class="card yellow"><div class="section-head"><h2>The good in today</h2><span class="mono">NIGHT / 02 MIN</span></div>${field('When did you feel most at peace today?','night.peace',day().night.peace,'Bring the moment back: where were you, and what made it feel peaceful?')}<button data-journal="night" class="wide-btn">Open evening reflection ↗</button></section><section class="card sage">${metrics()}</section></div></section>`}

const themes=['Begin where you are','Audit your ordinary day','Clear one surface','Name your attention traps','Write before asking AI','Define one research outcome','Review, don’t judge','Repeat your opening ritual','Try a new thinking spot','Read one paper deeply','Create a visible artifact','Make room for movement','Keep a playful project','Weekly reset','Practice a quiet walk','Notice the urge to switch','Write a decision memo','Reconnect with your reason','Choose depth over collecting','Protect real connection','Weekly reset','Adjust your challenge','Revisit your later list','Notice what restores you','Explain an idea in your words','Finish one small thing','Plan a gentle re-entry','Weekly reset','Compare with your baseline','Choose what stays'];
function renderMonth(){return `<section class="page-top"><div class="eyebrow">THE EXPERIMENT / ${esc(state.start)} — ${addDays(state.start,29)}</div><h1>Thirty days.<br><em>A little more you.</em></h1><p>Thirty chances to try something, learn about yourself, and make room for the life you want.</p></section><div class="phase-line">${[['01–07','Clear the noise','Review your routine and make time for the grant work.'],['08–14','Build a rhythm','Keep a regular start, add some movement, and record what you finish.'],['15–21','Stay with it','Spend longer on one question. Keep time for friends and side projects.'],['22–30','Choose what stays','Look at what helped you feel good and do work you care about. Bring those habits with you.']].map(x=>`<div class="phase"><span class="mono">DAYS ${x[0]}</span><h3>${x[1]}</h3><p class="small">${x[2]}</p></div>`).join('')}</div><div class="month-grid">${themes.map((t,i)=>{let dt=addDays(state.start,i);return `<button class="calendar-day ${hasEntry(dt)?'recorded':''} ${selected===dt?'selected':''}" data-date="${dt}"><span class="date">${new Date(dt+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span><span class="num">${String(i+1).padStart(2,'0')}</span><span class="theme">${t}</span><span class="small">${hasEntry(dt)?'● Entry saved':'○ Open day'} ${dt==='2026-10-31'?'· Grant month ends':''}</span></button>`}).join('')}</div>`}
function renderJournal(){let d=day();let forms={morning:morning(false),night:`${field('When did you feel most at peace today?','night.peace',d.night.peace,'What made that moment feel peaceful? What would you like more of?')}${field('Three things worth celebrating today','night.wins',d.night.wins,'What made you smile, helped you grow, or took a little courage?')}${field('Two things I’m glad I learned','night.lessons',d.night.lessons,'About the work or about myself.')}${field('What am I looking forward to starting tomorrow?','night.intention',d.night.intention,'Choose a first step that makes you want to begin.')}${field('What pulled me away? What was I needing then?','night.pull',d.night.pull,'Relief, novelty, reassurance, rest?')}${field('What did I think through in my own words?','night.thinking',d.night.thinking,'What clicked today? Follow the thought in your own words.')}${field('What can I put down for tonight?','night.unload',d.night.unload,'Write any loose thoughts or unfinished tasks. Choose when to return to the ones that matter.')}<a class="source-link" href="https://thedankoe.com/letters/why-productivity-advice-is-ruining-your-life/" target="_blank" rel="noopener">Journaling suggestion adapted from Koe’s Fill–Empty–Use framework ↗</a>`,weekly:`<p class="callout">Review how the week went. What took your time? What helped you focus? Use that to plan next week.</p>${field('Where did my time and energy actually go?','weekly.audit',d.weekly.audit,'When did you have energy? When were you tired?')}${field('What future am I moving toward—and what pattern do I want to leave?','weekly.direction',d.weekly.direction,'What would you like to change about your everyday life?')}${field('What matters next week across my three projects?','weekly.priorities',d.weekly.priorities,'What does each project need next? Which needs the most time?')}${field('What skill or resource would unlock the next step?','weekly.resources',d.weekly.resources,'Name a paper, skill, or person that could help with your current question.')}${field('What will I keep, remove, or rearrange?','weekly.change',d.weekly.change,'What change would make next week feel better?')}${weeklyExperiment()}`,map:`<p class="callout">Adapted from the public outline of Koe’s reset prompt. Its full interview is subscriber-only; these are original guiding questions.</p>${field('My vision: what would an ordinary good day feel like?','map.vision',state.map.vision||'Healthy and light; clear priorities; deep research thinking; drawing and real connection.','What would you be doing? How would you feel?')}${field('My anti-vision: what do I want to stop repeating?','map.anti',state.map.anti||'Fragmented work, scrolling in bed, reassurance through new commitments, and nights without a stopping point.','Which habits or situations keep coming up?')}${field('Why does this change matter to me personally?','map.why',state.map.why,'What would this change make possible for you?')}${field('My 30-day outcomes and longer direction','map.goals',state.map.goals,'What can I influence? How will I recognize progress?')}${field('Skills, resources, and support','map.skills',state.map.skills,'What do I need to learn, use, or ask for?')}${field('My first-week experiment','map.week',state.map.week,'What will you try this week, and when will you review it?')}`};return `<section class="page-top"><div class="eyebrow">A CONVERSATION WITH YOURSELF</div><h1>Leave a little<br><em>on the page.</em></h1><p>Follow the thought you want to explore. A few honest lines can be a good beginning.</p></section>${datebar()}<div class="journal-tabs">${[['morning','Morning'],['night','Night'],['weekly','Weekly'],['map','Life map']].map(([v,t])=>`<button data-jtab="${v}" class="${journalTab===v?'active':''}">${t}</button>`).join('')}</div><section class="card journal-form">${forms[journalTab]}<p class="small">Saved automatically on this device. Choose a previous date to revisit or continue an entry.</p></section>`}
function entries(){return Object.entries(state.days).filter(([dt])=>hasEntry(dt)).sort(([a],[b])=>a.localeCompare(b))}
function avg(arr,key){let v=arr.map(([,d])=>d.metrics[key]).filter(x=>x!==''&&x!==undefined&&Number.isFinite(Number(x))).map(Number);return v.length?(v.reduce((a,b)=>a+b,0)/v.length).toFixed(1):'—'}
function renderHistory(){let all=entries(),past=all.filter(([dt])=>dt<=selected&&dt>=addDays(selected,-6)),d=day();return `<section class="page-top"><div class="eyebrow">YOUR RECENT ENTRIES</div><h1>Look how<br><em>you’ve been.</em></h1><p>Look back at your sleep, focus, and work. Blank days have no entries. Patterns may suggest things to try, but they cannot tell you what caused a change.</p></section>${datebar()}<div class="stats"><div class="stat"><b>${past.length}</b><span class="small">days recorded / last 7</span></div><div class="stat"><b>${avg(past,'sleep')}</b><span class="small">hours sleep / recorded days</span></div><div class="stat"><b>${avg(past,'fog')}</b><span class="small">brain fog / 10</span></div><div class="stat"><b>${past.reduce((s,[,x])=>s+Number(x.metrics.artifacts||0),0)}</b><span class="small">research outputs / last 7</span></div></div><section class="card"><div class="section-head"><h2>Movement</h2><span class="mono">LAST 7 DAYS</span></div><div class="bar-chart">${Array.from({length:7},(_,i)=>{let dt=addDays(selected,i-6),v=state.days[dt]?.metrics.movement;return `<div class="chart-col" title="${dt}: ${v??'unrecorded'}"><span>${v??'—'}</span><div class="chart-bar" style="height:${v===undefined?0:Math.min(110,Number(v)/Math.max(60,...past.map(([,x])=>Number(x.metrics.movement||0)))*110)}px"></div><span>${dt.slice(5)}</span></div>`}).join('')}</div><div class="history-table"><table><thead><tr><th>Date</th><th>Sleep</th><th>Fog</th><th>Flow</th><th>Scroll min</th><th>Artifacts</th><th>Tasks</th></tr></thead><tbody>${all.length?all.slice().reverse().map(([dt,x])=>`<tr><td><button class="small" data-history-date="${dt}">${esc(dt)}</button></td><td>${esc(x.metrics.sleep??'—')}</td><td>${esc(x.metrics.fog??'—')}</td><td>${esc(x.metrics.flow??'—')}</td><td>${esc(x.metrics.scroll??'—')}</td><td>${esc(x.metrics.artifacts??'—')}</td><td>${x.tasks.filter(t=>t.done).length}/${x.tasks.length}</td></tr>`).join(''):'<tr><td colspan="7">Your first entry starts the story. Come back to see what changes.</td></tr>'}</tbody></table></div></section><section class="card" style="margin-top:20px"><h2>${esc(dateLabel(selected))}</h2>${['morning','focus','night','weekly'].map(k=>`<div class="saved-entry"><h3>${k==='morning'?'Morning':k==='night'?'Evening':k==='focus'?'Focus notes':'Weekly'}</h3>${Object.entries(d[k]||{}).filter(([,v])=>v!==''&&v!==undefined).map(([a,b])=>`<p><strong>${esc(({excited:'What excited me',fear:'What scared me',must:'What I wanted to do',peace:'Most at peace',wins:'Wins',lessons:'Lessons',intention:'Next intention',pull:'What pulled me away',thinking:'My own thinking',unload:'Putting down for tonight',question:'My research question',finish:'What counts as progress',resume:'Where to resume',technique:'Technique tried',observation:'How it went',wish:'My wish',outcome:'Desired outcome',obstacle:'Inner obstacle',ifthen:'My if–then plan',plus:'What worked',minus:'What did not work',next:'What to try next'})[a]||a)}</strong><br>${esc(b)}</p>`).join('')||'<p class="small">No reflection recorded.</p>'}</div>`).join('')}<button data-journal="night">Continue this entry ↗</button></section>`}
function renderGuide(){return `<section class="page-top"><div class="eyebrow">A SMALL FIELD GUIDE</div><h1>Less collecting.<br><em>More becoming.</em></h1><p>The ideas behind your plan, what we changed to fit your life, and the sources if you want to read more.</p></section><div class="two-col"><div class="stack"><section class="card sage"><h2 style="margin-bottom:20px">Your app boundaries</h2><div class="guide-item"><h3>Rednote, TikTok, and Instagram</h3><p>Rednote, TikTok, and Instagram are paused for this experiment. This site cannot block other apps; use your device’s app limits or remove shortcuts.</p></div><div class="guide-item"><h3>Use X for research</h3><p>Use the 20-minute window to look for something specific. Save useful links with a note about why you want to read them. Keeping X is your adaptation of Koe’s plan.</p></div><div class="guide-item"><h3>What to do instead</h3><p>Keep time for drawing, side projects, and friends. When you reach for a feed, try drawing or taking a short walk. Notice whether you wanted a break or were avoiding something.</p></div></section><section class="card"><h2 style="margin-bottom:20px">What Koe actually proposes</h2><p>The reset prompt’s public outline covers your desired direction, an unwanted future, goals, skills, resources, routine, and a first-week plan. The full interview is paywalled.</p><p>His detox article recommends writing why you want to change, taking a 30-day break from feeds and other compulsive habits, walking, strength training, changing your diet, working on a project, and reflecting at night.</p><p class="small">Your plan starts with walks and regular meals. It does not include his elimination diet. Treat the month as a way to test habits; a change in dopamine receptors is not an established outcome of this plan.</p><a class="source-link" href="https://letters.thedankoe.com/p/a-prompt-to-reset-your-life-in-30" target="_blank" rel="noopener">Read: A Prompt to Reset Your Life in 30 Days ↗</a><a class="source-link" href="https://letters.thedankoe.com/p/a-dopamine-detox-to-reset-your-life" target="_blank" rel="noopener">Read: A Dopamine Detox to Reset Your Life in 30 Days ↗</a></section><section class="card"><h2 style="margin-bottom:18px">The 30-minute audit</h2><p>Spend ten minutes writing down yesterday and how you felt, ten deciding what to keep or change, and ten planning next week around your commitments.</p><p class="small">The three ten-minute allocations are this site’s structure. Koe’s short reset post describes auditing, prioritizing/removing/restructuring, and planning a week.</p><button data-journal="weekly">Do the audit ↗</button><a class="source-link" href="https://www.linkedin.com/posts/thedankoe_how-to-reset-your-life-activity-7288213102385381377-LwZi" target="_blank" rel="noopener">Source: Koe’s hard reset post ↗</a></section></div><div class="stack"><section class="card pink"><h2 style="margin-bottom:20px">Your way into flow</h2><p>You said a new place, coffee, and writing help you settle into work. Try repeating that routine and use the flow tracker to see whether it helps.</p><p>Flow research points to clear goals, useful feedback, a manageable challenge, and some choice over the work. A diary study found that multitasking could get in the way of flow. These findings can guide your setup, but they do not guarantee it.</p><p>Before opening more tabs, write for five minutes: “What am I trying to answer? What do I think so far?” At the end, save a note, a decision, or a result.</p><p class="small">Five minutes is a starting point. Adjust it to suit you; coffee is optional.</p><a class="source-link" href="https://www.nature.com/articles/s44271-024-00115-3" target="_blank" rel="noopener">Durcan et al. (2024): framework for flow experiments ↗</a><a class="source-link" href="https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2024.1384453/full" target="_blank" rel="noopener">Original diary study (2024): multitasking and flow ↗</a></section><section class="card"><h2 style="margin-bottom:20px">AI as a thinking partner</h2><p>Write your question and what you think first. Then ask the model to check your reasoning or help with a specific passage. Check its citations in the original paper.</p><p class="callout">“Ask me to explain my current reasoning first. Challenge one assumption at a time. Help me find evidence; let me attempt the answer before you explain it.”</p><p>While the model runs, keep working in your notes instead of opening a feed. Afterward, write what you learned and what you still need to figure out.</p></section><section class="card yellow"><h2 style="margin-bottom:18px">How your day is shaped</h2><p>The default planner uses explicit rules: wake time, energy, your must-do, day of week, and fixed commitments. Low energy shortens focus blocks; Thursday and Friday get another block on the lead question. Blue fixed blocks keep their times.</p><p>Connect the optional AI planner in Settings to turn your must-do brain dump into prioritized tasks inside existing focus and research blocks. Morning rituals, meals, walks, X, dinner, and wind-down keep their times and durations. It shows estimates and lists work that cannot fit. Your provider key stays on your backend; API usage is billed by your provider.</p><p>Your answer about fear stays in your journal; it does not change your schedule. Review a new plan before applying it. Anything that will not fit is listed separately.</p></section><section class="card"><h2 style="margin-bottom:18px">Health is part of the work</h2><p class="small">Brain fog has persisted since summer: arrange a campus health appointment rather than assuming feeds explain it. Keep meals and sleep regular, and build movement gradually. If reducing caffeine, taper rather than making several abrupt changes at once. Creatine is not a direct substitute for coffee; it is not included as a treatment in this plan.</p><a class="source-link" href="https://www.nhs.uk/symptoms/tiredness-and-fatigue/" target="_blank" rel="noopener">NHS: persistent tiredness and when to seek help ↗</a></section></div></div>${tipLibrary()}<section class="card" id="collection" style="margin-top:24px"><div class="section-head"><h2>Saved links and ideas</h2><span class="mono">READ / IDEAS / OPPORTUNITIES</span></div><form id="inboxForm" class="inbox-form"><div class="inline-fields"><input id="inboxTitle" placeholder="What is worth keeping?" aria-label="Collection title" required maxlength="300"><select id="inboxCategory" aria-label="Collection category"><option>Read</option><option>Ideas</option><option>Opportunities</option></select></div><input id="inboxUrl" type="url" placeholder="Link (optional)" aria-label="Collection URL"><input id="inboxWhy" placeholder="Why does it matter? / next question" aria-label="Why keep this"><button class="primary">Keep it for later ＋</button></form>${state.inbox.length?state.inbox.slice().reverse().map(x=>`<div class="inbox-item"><div class="title-line"><span>${esc(x.title)}</span><button class="small" data-delete-idea="${esc(x.id)}" aria-label="Remove ${esc(x.title)}">×</button></div><span class="tag">${esc(x.category)}</span> <span class="small">${esc(x.date)}</span>${x.why?`<p>${esc(x.why)}</p>`:''}${/^https?:\/\//i.test(x.url||'')?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Open source ↗</a>`:''}</div>`).join(''):'<p class="empty">No saved items yet.</p>'}</section>`}
function render(){VoiceInput.stop();CalendarUI.destroy();let renderers={today:renderToday,month:renderMonth,journal:renderJournal,history:renderHistory,guide:renderGuide};$('#main').innerHTML=renderers[view]();$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));bind();bindCalendar();SiteMotion.refresh(view,!!state.ambient);if(!storageOK)$('#saveState').textContent='Storage unavailable · export a backup in settings';}
function navigate(v){view=v;render();window.scrollTo({top:0,behavior:'instant'})}
function setPath(path,value){let parts=path.split('.'),target=parts[0]==='map'?state:day();while(parts.length>1){let p=parts.shift();target[p]??={};target=target[p]}target[parts[0]]=value;save()}
function bind(){
$('#nextTip')?.addEventListener('click',()=>{visitTip=FlowTips.pick(visitTip.id);state.lastTipId=visitTip.id;save();render();$('#nextTip')?.focus({preventScroll:true})});
$('#recordTip')?.addEventListener('click',()=>{day().focus??={};day().focus.technique=visitTip.title;save();toast('Added to today’s focus notes.');});
$$('[data-open-tips]').forEach(b=>b.onclick=()=>{navigate('guide');$('#tipLibrary').scrollIntoView({behavior:'smooth'})});

$$('[data-bind]').forEach(el=>el.addEventListener(el.type==='checkbox'||el.tagName==='SELECT'?'change':'input',()=>{if(el.type==='number'&&!el.checkValidity())return;setPath(el.dataset.bind,el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?'':Number(el.value)):el.value)}));
$('#dateSelect')?.addEventListener('change',e=>{if(e.target.value){selected=e.target.value;render()}});$('#prevDate')?.addEventListener('click',()=>{selected=addDays(selected,-1);render()});$('#nextDate')?.addEventListener('click',()=>{selected=addDays(selected,1);render()});$('#goToday')?.addEventListener('click',()=>{selected=today();render()});
$$('[data-date]').forEach(b=>b.onclick=()=>{let inCalendar=!!b.closest('.cal-week-strip'),position=window.scrollY;selected=b.dataset.date;if(inCalendar){view='today';render();window.scrollTo({top:position,behavior:'instant'})}else navigate('today')});$$('[data-history-date]').forEach(b=>b.onclick=()=>{selected=b.dataset.historyDate;render()});
$$('[data-journal]').forEach(b=>b.onclick=()=>{journalTab=b.dataset.journal;navigate('journal')});$$('[data-jtab]').forEach(b=>b.onclick=()=>{journalTab=b.dataset.jtab;render()});
$('#taskForm')?.addEventListener('submit',e=>{e.preventDefault();let text=$('#taskText').value.trim();if(text){day().tasks.push({text,done:false});save();render();$('#taskText').focus()}});$$('[data-task]').forEach(b=>b.onchange=()=>{day().tasks[+b.dataset.task].done=b.checked;save();render()});$$('[data-delete-task]').forEach(b=>b.onclick=()=>{day().tasks.splice(+b.dataset.deleteTask,1);save();render()});
$('#quickIdea')?.addEventListener('submit',e=>{e.preventDefault();let title=$('#ideaText').value.trim();if(title){state.inbox.push({id:crypto.randomUUID(),title,category:'Ideas',date:selected});save();render();toast('Idea saved.')}});$$('[data-open-inbox]').forEach(b=>b.onclick=()=>{navigate('guide');$('#collection').scrollIntoView({behavior:'smooth'})});
$('#inboxForm')?.addEventListener('submit',e=>{e.preventDefault();let title=$('#inboxTitle').value.trim();if(!title)return;state.inbox.push({id:crypto.randomUUID(),title,category:$('#inboxCategory').value,url:$('#inboxUrl').value.trim(),why:$('#inboxWhy').value.trim(),date:selected});save();render();$('#collection').scrollIntoView()});$$('[data-delete-idea]').forEach(b=>b.onclick=()=>{if(confirm('Remove this saved item?')){state.inbox=state.inbox.filter(x=>x.id!==b.dataset.deleteIdea);save();render();$('#collection').scrollIntoView()}});
$('#generatePlan')?.addEventListener('click',()=>previewPlan());$('#addBlock')?.addEventListener('click',()=>editBlock(-1));$$('[data-edit]').forEach(b=>b.onclick=()=>editBlock(+b.dataset.edit));$$('[data-move]').forEach(b=>b.onclick=()=>{let[i,dir]=b.dataset.move.split(',').map(Number),s=currentSchedule();let j=i+dir;while(j>=0&&j<s.length&&s[j].type==='fixed')j+=dir;if(j>=0&&j<s.length)swapBlocks(i,j)});
$$('.block[draggable=true]').forEach(b=>{b.ondragstart=e=>{dragId=b.dataset.id;e.dataTransfer.setData('text/plain',dragId);b.classList.add('dragging')};b.ondragend=()=>b.classList.remove('dragging')});$$('.block').forEach(b=>{b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();let s=currentSchedule();let from=s.findIndex(x=>x.id===dragId),to=s.findIndex(x=>x.id===b.dataset.id);if(from>=0&&to>=0)swapBlocks(from,to)}});
$('#timerStart')?.addEventListener('click',toggleTimer);$('#timerReset')?.addEventListener('click',()=>{clearInterval(timerInterval);timerRunning=false;timerLeft=1500;updateTimer()});
}
function modal(html){let el=document.createElement('dialog');el.innerHTML=html;document.body.appendChild(el);el.addEventListener('close',()=>el.remove());SiteMotion.pause();el.addEventListener('close',()=>SiteMotion.resume());el.showModal();return el}
function previewPlan(useDefault=false){let fixed=currentSchedule().filter(b=>b.type==='fixed');let errors=P.conflicts(fixed);if(errors.length){toast('Fix overlapping or invalid fixed commitments before generating.');return}let result=P.makePlan(selected,day().morning,fixed);
if(!useDefault&&typeof AIPlanner!=='undefined'&&AIPlanner.config().endpoint&&day().morning.must?.trim()){
 if(!AIPlanner.ready()){toast('Enter your planner access code in Settings for this session.');$('#settingsBtn').click();return}
 generateAIPlan(fixed);return;
}
showPlanPreview(result);
}
function showPlanPreview(result){let el=modal(`<h2 style="margin-bottom:18px">A possible day.</h2><p class="small">Review your tasks and schedule before saving. Existing tasks and checkmarks stay saved.</p>${result.tasks?'<details open><summary>Your to-do list · time estimates</summary><ul>'+result.tasks.map(t=>'<li>'+esc(t.title)+(t.category==='work'?' · Priority '+t.priority:' · Routine')+' · '+t.duration+' min'+(t.estimated?' (estimate)':'')+(t.preference?' · '+esc(t.preference):'')+'</li>').join('')+'</ul></details>':''}${result.reasons.map(x=>`<p class="small">${esc(x)}</p>`).join('')}<div style="max-height:42vh;overflow:auto">${result.blocks.map(b=>`<p><span class="mono">${b.start}</span> · ${esc(b.title)} <span class="small">(${b.duration} min)</span></p>`).join('')}</div>${result.unscheduled.length?`<p class="callout">Could not fit before your finish time: ${result.unscheduled.map(esc).join('; ')}. Edit your commitments or choose what to defer.</p>`:''}<div class="button-row"><button class="primary" id="acceptPlan">${result.tasks?'Use schedule + to-do list':'Use this schedule'}</button>${result.tasks?'<button id="acceptTasks">Use to-do list only</button>':''}<button id="cancelPlan">Keep current</button></div>`);el.querySelector('#cancelPlan').onclick=()=>el.close();el.querySelector('#acceptPlan').onclick=()=>{rememberSchedule();day().schedule=result.blocks;day().planReasons=result.reasons;day().parsedTasks=result.tasks||[];if(result.tasks)mergeAITasks(result.tasks);save();el.close();navigate('today');toast(result.tasks?'Your schedule and to-do list are saved.':'Schedule saved. Use Give feedback to adjust it.')};
el.querySelector('#acceptTasks')?.addEventListener('click',()=>{mergeAITasks(result.tasks);day().parsedTasks=result.tasks;save();el.close();navigate('today');toast('Your to-do list is saved. Your schedule stays as it was.')});}
function mergeAITasks(parsed){
 const normalize=s=>String(s).trim().toLocaleLowerCase().replace(/\s+/g,' ');
 for(const t of [...parsed].sort((a,b)=>a.priority-b.priority)){
  const existing=day().tasks.find(x=>normalize(x.text)===normalize(t.title));
  const metadata={duration:t.duration,estimated:t.estimated,priority:t.priority,category:t.category,source:'ai'};
  if(existing)Object.assign(existing,metadata);
  else day().tasks.push({text:t.title,done:false,...metadata});
 }
}
async function generateAIPlan(fixed){
 VoiceInput.stop();
 const date=selected,m=structuredClone(day().morning);
 const el=modal('<h2>Making room for your day.</h2><p role="status" id="aiProgress">Prioritizing your tasks inside your work blocks. Meals, breaks, and your routine stay in place…</p><p class="small">Your current schedule stays as it is until you accept a new one.</p><div class="button-row"><button id="cancelAI">Cancel</button><button id="defaultAI" hidden>Use default planner</button></div>');
 let cancelled=false;el.addEventListener('close',()=>{cancelled=true});el.querySelector('#cancelAI').onclick=()=>el.close();
 el.querySelector('#defaultAI').onclick=()=>{el.close();previewPlan(true)};
 try{
  const result=await AIPlanner.plan(date,m,fixed);
  if(cancelled)return;
  if(selected!==date||JSON.stringify(day().morning)!==JSON.stringify(m)){el.close();toast('Your date or answers changed. Shape your day again.');return}
  el.close();showPlanPreview(result);
 }catch(error){if(cancelled)return;el.querySelector('#aiProgress').textContent=error.message;el.querySelector('#defaultAI').hidden=false;}
}
function swapBlocks(i,j){if(i===j)return;let s=structuredClone(currentSchedule());if(s[i].type==='fixed'||s[j].type==='fixed'){toast('Fixed commitments stay put. Edit their times directly.');return}let a=s[i].start,b=s[j].start;s[i].start=b;s[j].start=a;let errs=P.conflicts(s);if(errs.length){toast('Those durations would overlap. Edit the times to make room.');return}s.sort((a,b)=>P.mins(a.start)-P.mins(b.start));day().schedule=s;save();render()}
function editBlock(index,preset={}){let s=structuredClone(currentSchedule()),b=index>=0?s[index]:{title:'',start:preset.start||'17:00',duration:preset.duration||30,type:'work'};let el=modal(`<h2 style="margin-bottom:20px">${index<0?'Make a little room.':'Move things around.'}</h2><form id="blockForm">${field('Block name','',b.title,'A specific, finishable activity','text')}<label class="field"><span>Start time</span><input id="blockStart" type="time" value="${b.start}" required></label><label class="field"><span>Minutes</span><input id="blockDuration" type="number" min="5" max="720" step="5" value="${b.duration}" required></label><label class="field"><span>Kind</span><select id="blockType">${[['work','Work'],['focus','Focus'],['rest','Rest / ritual'],['fixed','Fixed commitment']].map(([v,t])=>`<option value="${v}" ${v===b.type?'selected':''}>${t}</option>`).join('')}</select></label><p id="blockError" class="small" role="alert"></p><div class="button-row"><button class="primary">Save block</button><button type="button" id="closeBlock">Cancel</button>${index>=0?'<button type="button" id="removeBlock">Remove</button>':''}</div></form>`);el.querySelector('input[data-bind]').required=true;el.querySelector('#closeBlock').onclick=()=>el.close();el.querySelector('#removeBlock')?.addEventListener('click',()=>{let button=el.querySelector('#removeBlock');if(button.dataset.confirm==='yes'){s.splice(index,1);el.close();commitSchedule(s,'Block removed')}else{button.dataset.confirm='yes';button.textContent='Confirm removal';el.querySelector('#blockError').textContent='Remove this block from today? You can undo this change.'}});el.querySelector('#blockForm').onsubmit=e=>{e.preventDefault();let title=el.querySelector('input[data-bind]').value.trim();if(!title)return;let update={...b,id:b.id||crypto.randomUUID(),title,start:el.querySelector('#blockStart').value,duration:Number(el.querySelector('#blockDuration').value),type:el.querySelector('#blockType').value};if(index<0)s.push(update);else s[index]=update;let errs=P.conflicts(s);if(errs.length){el.querySelector('#blockError').textContent=errs.join('. ');return}el.close();commitSchedule(s.sort((a,b)=>P.mins(a.start)-P.mins(b.start)),'Block saved')};}
function timerText(){return `${String(Math.floor(timerLeft/60)).padStart(2,'0')}:${String(timerLeft%60).padStart(2,'0')}`}
function updateTimer(){if($('#timerDisplay'))$('#timerDisplay').textContent=timerText();if($('#timerStart'))$('#timerStart').textContent=timerRunning?'Pause':timerLeft===1500?'Begin 25 min':'Continue'}
function toggleTimer(){if(timerRunning){clearInterval(timerInterval);timerRunning=false;updateTimer();return}if(timerLeft===0)timerLeft=1500;timerRunning=true;let end=Date.now()+timerLeft*1000;timerInterval=setInterval(()=>{timerLeft=Math.max(0,Math.ceil((end-Date.now())/1000));if(timerLeft===0){clearInterval(timerInterval);timerRunning=false;toast('Time is up. Save your notes, then take a break.')}updateTimer()},250);updateTimer()}
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#settingsBtn').onclick=()=>{if(typeof AIPlanner!=='undefined'){let c=AIPlanner.config();$('#aiEndpoint').value=c.endpoint;$('#aiAccess').value=c.token;$('#aiStatus').textContent=AIPlanner.ready()?'Connected for this session.':'AI is off until your backend and access code are connected.';}$('#startSetting').value=state.start;$('#tzSetting').value=state.tz;$('#ambientSetting').checked=!!state.ambient;$('#settings').showModal()};$('#startSetting').onchange=e=>{if(e.target.value){state.start=e.target.value;save();render()}};$('#tzSetting').onchange=e=>{state.tz=e.target.value;save();render()};
$('#saveAI').onclick=()=>{try{AIPlanner.setConfig($('#aiEndpoint').value,$('#aiAccess').value);$('#aiStatus').textContent=AIPlanner.ready()?'Connection saved. Shape my day will turn your daily answer into tasks and a schedule.':'Connection incomplete. Enter your backend URL and access code.';render()}catch(e){$('#aiStatus').textContent=e.message}};
$('#disconnectAI').onclick=()=>{AIPlanner.setConfig('','');$('#aiEndpoint').value='';$('#aiAccess').value='';$('#aiStatus').textContent='Disconnected. The default planner is available.';render()};
$('#ambientSetting').checked=!!state.ambient;$('#ambientSetting').onchange=e=>{state.ambient=e.target.checked;save();SiteMotion.refresh(view,state.ambient)};
$('#exportBtn').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`still-days-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Backup downloaded. Keep it somewhere safe.')};
function validBackup(v){if(!v||v.version!==1||!/^\d{4}-\d{2}-\d{2}$/.test(v.start)||!['America/New_York','America/Los_Angeles'].includes(v.tz)||!v.days||typeof v.days!=='object'||Array.isArray(v.days)||!v.map||typeof v.map!=='object'||!Array.isArray(v.inbox))return false;for(let[dt,d]of Object.entries(v.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(dt)||!d||!['morning','night','weekly','metrics'].every(k=>d[k]&&typeof d[k]==='object')||!Array.isArray(d.tasks)||!d.tasks.every(t=>t&&typeof t.text==='string'&&typeof t.done==='boolean'))return false;if(d.schedule&&(!Array.isArray(d.schedule)||d.schedule.some(b=>!b||typeof b.title!=='string'||typeof b.id!=='string'||!['work','rest','focus','fixed'].includes(b.type))||P.conflicts(d.schedule).length))return false;}return v.inbox.every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.category==='string')}
$('#importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup is too large (10 MB maximum).');let text=await file.text();if(/"(?:__proto__|constructor|prototype)"\s*:/.test(text))throw Error('Unsupported backup fields.');let v=JSON.parse(text);if(!validBackup(v))throw Error('This file is not a valid Still Days backup.');if(!confirm('Replace all entries on this device with this backup? Export your current entries first if you want to keep them.'))return;state=v;save();selected=today();render();$('#importMsg').textContent='Backup restored.';toast('Your entries are back.')}catch(err){$('#importMsg').textContent=err.message}finally{e.target.value=''}};
save();
render();
